#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> findValidElements(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 2) return nums;
        std::vector<int> right(n);
        int currMax = -2e9;
        for (int i = n - 1; i >= 0; --i) {
            currMax = std::max(currMax, nums[i]);
            right[i] = currMax;
        }
        std::vector<int> ans;
        int leftMax = -2e9;
        for (int i = 0; i < n; ++i) {
            bool isLeft = (i == 0 || nums[i] > leftMax);
            bool isRight = (i == n - 1 || nums[i] > right[i + 1]);
            if (isLeft || isRight) {
                ans.push_back(nums[i]);
            }
            leftMax = std::max(leftMax, nums[i]);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] findValidElements(int[] nums) {
        int n = nums.length;
        if (n <= 2) return nums.clone();
        int[] right = new int[n];
        int currMax = Integer.MIN_VALUE;
        for (int i = n - 1; i >= 0; i--) {
            currMax = Math.max(currMax, nums[i]);
            right[i] = currMax;
        }
        List<Integer> list = new ArrayList<>();
        int leftMax = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            boolean isLeft = (i == 0 || nums[i] > leftMax);
            boolean isRight = (i == n - 1 || nums[i] > right[i + 1]);
            if (isLeft || isRight) {
                list.add(nums[i]);
            }
            leftMax = Math.max(leftMax, nums[i]);
        }
        int[] ans = new int[list.size()];
        for (int i = 0; i < list.size(); i++) ans[i] = list.get(i);
        return ans;
    }
}

